    intent: "Probleemgerichte uitleg over responstijd bij nieuwe leads zonder onbewezen universele benchmarks.", searchIntent: "probleemgericht", primaryKeyword: "hoe snel lead opvolgen", audience: "Sales- en serviceteams die nieuwe aanvragen prioriteren.", promise: "Je maakt een responstijdbeleid dat past bij de klantvraag.", conversion: "Verdeel leads op urgentie, koopintentie en benodigde actie.",
    keywords: ["hoe snel lead opvolgen", "responstijd leads", "nieuwe lead bellen", "lead buiten openingstijd", "snelle leadopvolging"], relatedArticles: ["wat-is-ai-leadopvolging", "roi-automatische-leadopvolging-berekenen", "wat-is-een-ai-telefoniste"], relatedProducts: ["ai-leadopvolger", "ai-telefoniste"], relatedNiches: ["autobedrijven", "makelaars", "zonnepanelen"],
    summary: ["Een live chat, gemiste oproep en vrijblijvende download hebben niet dezelfde gewenste responstijd.", "Reageer snel genoeg om context en verwachting vast te houden, maar stuur geen leeg ontvangstbericht wanneer een gerichte vraag of actie mogelijk is.", "Ontwerp servicelevels per intentie en kanaal, plus een fallback wanneer agenda, CRM of verantwoordelijke medewerker niet beschikbaar is."],
    sections: [
      { id: "geen-universeel-getal", eyebrow: "Nuance", title: "Er bestaat geen geloofwaardig universeel aantal minuten voor iedere lead", paragraphs: ["Online artikelen noemen vaak één ideaal getal. Zonder context over branche, kanaal, campagne, product en onderzoeksopzet zegt zo’n benchmark weinig. Een spoedaanvraag is iets anders dan iemand die een gids downloadt.", "Bepaal responstijd vanuit de klantverwachting. Wie in een live kanaal een concrete voorraad- of afspraakvraag stelt, verwacht sneller antwoord dan iemand die expliciet informatie voor later aanvraagt.", "Snelheid zonder relevantie kan juist frictie veroorzaken. Een generiek bericht dat opnieuw vraagt wat al in het formulier staat, is technisch snel maar inhoudelijk traag."] },
      { id: "prioriteitsmodel", eyebrow: "Prioriteit", title: "Gebruik intentie, tijdgevoeligheid en actie als prioriteitsmodel", paragraphs: ["Geef hoge prioriteit aan vragen waarbij beschikbaarheid verandert, de klant nu wil handelen of veiligheid speelt. Plan informatievragen en lange oriëntatie anders in.", "Leg per klasse vast wie eigenaar is, wat de eerste reactie moet bereiken en wanneer de route escaleert."], bullets: ["Nu: live gesprek, gemiste oproep, afspraak of schaarse beschikbaarheid", "Vandaag: concrete offerte-, voorraad- of servicevraag", "Gepland: oriëntatie, nurture of een toekomstige hercontactdatum", "Mens direct: klacht, emotie, veiligheid of inhoudelijk oordeel"] },
      { id: "buiten-openingstijd", eyebrow: "Buiten openingstijd", title: "Automatisering kan de wachttijd benutten zonder te doen alsof alles direct kan", paragraphs: ["Buiten openingstijd kan AI de vraag erkennen, relevante gegevens verzamelen en beschikbare momenten aanbieden. Als een medewerker of systeem nodig is, vermeldt de route eerlijk wanneer bevestiging volgt.", "Zo begint de volgende werkdag met complete context in plaats van een naam en telefoonnummer. De klant krijgt ondertussen duidelijkheid over de volgende stap."] }
    ],
    examples: [{ title: "Voorraadlead", text: "De AI controleert het voertuig, vraagt naar proefrit en inruil en geeft een concreet vervolg. Niet alleen: ‘we nemen contact op’." }, { title: "Offerteoriëntatie", text: "De lead ontvangt relevante uitleg en kiest zelf een terugbelmoment, zonder ’s avonds onverwacht gebeld te worden." }],
    faq: [{ question: "Moet je iedere lead direct bellen?", answer: "Nee. Kanaalvoorkeur, toestemming, intentie en tijdstip bepalen wat passend is. Soms is een inhoudelijke chat- of e-mailreactie beter." }, { question: "Is een automatisch ontvangstbericht genoeg?", answer: "Het bevestigt ontvangst, maar lost de informatiebehoefte niet op. Verzamel waar mogelijk direct de context voor een bruikbare volgende stap." }, { question: "Hoe stel je een servicelevel vast?", answer: "Analyseer leadtypen, klantverwachting, beschikbaarheid en huidige uitval. Definieer per klasse een eigenaar, eerste actie en escalatiemoment en test dit in de praktijk." }],
